mapper.select:
SELECT DISTINCT fpadd.PORTFOLIO_ID prodId, fp.FINPROD_ABBR combinationname,/*组合名称*/ fpadd.prod_manager prodManager, users.real_name manager,/*产品经理*/ i.amt cleancashflownextday,/*未来隔夜净现金流*/ j.amt cleancashflowsevenday,/*未来7日净现金流*/ k.amt cleancashflowonemonth /*未来1个月净现金流*/ FROM ( select PORTFOLIO_ID from PTL_SEC_VALUTION WHERE CDATE = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') GROUP BY PORTFOLIO_ID ) match LEFT JOIN fin_product fp ON match.PORTFOLIO_ID = fp.FINPROD_MARKET_ID LEFT JOIN FIN_PRODUCT_add fpadd ON fpadd.FINPROD_ID = fp.FINPROD_ID LEFT JOIN sys_user users ON users.USER_NAME = fpadd.prod_manager LEFT JOIN ( SELECT prod_id, nvl(nhgexpire,0)+nvl(zhgsq,0)+nvl(ccexpire,0)+nvl(crsq,0)+nvl(assetexpire,0)+nvl(assetpayments,0)+nvl(prodexpire,0)+nvl(nhgsq,0)+nvl(zhgexpire,0)+nvl(ccsq,0)+nvl(crexpire,0)+nvl(crsqs,0) amt/*净现金流*/ FROM ( select z.prod_id,A.nhgexpire,B.zhgsq,C.ccexpire,D.crsq,E.assetexpire,F.assetpayments,G.prodexpire, H.nhgsq,I.zhgexpire,J.ccsq,K.crexpire,L.crsqs from (select distinct PORTFOLIO_ID prod_id from DetailFutureOne) z left join /*逆回购到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) nhgexpire from DetailFutureOne where CASHFLOWTYPE in ('F03','F05') AND PS = 'T02' group by PORTFOLIO_ID) A on a.prod_id = z.prod_id left join /*正回购首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) zhgsq from DetailFutureOne where CASHFLOWTYPE in ('F02', 'F04') AND PS = 'T01' group by PORTFOLIO_ID) B on b.prod_id = z.prod_id left join /*拆出到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) ccexpire from DetailFutureOne where CASHFLOWTYPE in ('F09') and ps = 'T02' group by PORTFOLIO_ID) C on c.prod_id = z.prod_id left join /*拆入首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) crsq from DetailFutureOne where CASHFLOWTYPE in ('F25') and ps = 'T01' group by PORTFOLIO_ID) D on d.prod_id = z.prod_id /*拆入到期*/ left join (select PORTFOLIO_ID prod_id,sum(CASHFLOW)*-1 crsqs from DetailFutureOne where CASHFLOWTYPE in ('F08') and ps = 'T01' group by PORTFOLIO_ID) L on l.prod_id = z.prod_id left join /*资产到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) assetexpire from DetailFutureOne where CASHFLOWTYPE in ('F01','F07','F17','F18') and cash_type = '02' group by PORTFOLIO_ID) E on e.prod_id = z.prod_id left join /*资产中间收息*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) assetpayments from DetailFutureOne where CASHFLOWTYPE in ('F01','F07','F17','F18') and cash_type = '01' group by PORTFOLIO_ID) F on f.prod_id = z.prod_id left join /*产品到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW)*-1 prodexpire from DetailFutureOne where CASHFLOWTYPE in ('F16','F24') group by PORTFOLIO_ID) G on g.prod_id = z.prod_id left join /*逆回购首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) nhgsq from DetailFutureOne where CASHFLOWTYPE in ('F03','F05') AND PS = 'T01' group by PORTFOLIO_ID) H on h.prod_id = z.prod_id left join /*正回购到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) zhgexpire from DetailFutureOne where CASHFLOWTYPE in ('F02', 'F04') AND PS = 'T02' group by PORTFOLIO_ID) I on i.prod_id = z.prod_id left join /*拆出首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) ccsq from DetailFutureOne where CASHFLOWTYPE in ('F09') AND PS = 'T01' group by PORTFOLIO_ID) J on j.prod_id = z.prod_id left join /*拆入到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) crexpire from DetailFutureOne where CASHFLOWTYPE in ('F25') and ps = 'T02' group by PORTFOLIO_ID) K on k.prod_id = z.prod_id ) ) i /*未来隔夜净现金流*/ ON i.prod_id = fp.FINPROD_MARKET_ID left join ( SELECT prod_id, nvl(nhgexpire,0)+nvl(zhgsq,0)+nvl(ccexpire,0)+nvl(crsq,0)+nvl(assetexpire,0)+nvl(assetpayments,0)+nvl(prodexpire,0)+nvl(nhgsq,0)+nvl(zhgexpire,0)+nvl(ccsq,0)+nvl(crexpire,0)+nvl(crsqs,0) amt/*净现金流*/ FROM ( select z.prod_id,A.nhgexpire,B.zhgsq,C.ccexpire,D.crsq,E.assetexpire,F.assetpayments,G.prodexpire, H.nhgsq,I.zhgexpire,J.ccsq,K.crexpire,L.crsqs from (select distinct PORTFOLIO_ID prod_id from DetailFutureSeven) z left join /*逆回购到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) nhgexpire from DetailFutureSeven where CASHFLOWTYPE in ('F03','F05') AND PS = 'T02' group by PORTFOLIO_ID) A on a.prod_id = z.prod_id left join /*正回购首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) zhgsq from DetailFutureSeven where CASHFLOWTYPE in ('F02', 'F04') AND PS = 'T01' group by PORTFOLIO_ID) B on b.prod_id = z.prod_id left join /*拆出到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) ccexpire from DetailFutureSeven where CASHFLOWTYPE in ('F09') and ps = 'T02' group by PORTFOLIO_ID) C on c.prod_id = z.prod_id left join /*拆入首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) crsq from DetailFutureSeven where CASHFLOWTYPE in ('F25') and ps = 'T01' group by PORTFOLIO_ID) D on d.prod_id = z.prod_id /*拆入到期*/ left join (select PORTFOLIO_ID prod_id,sum(CASHFLOW)*-1 crsqs from DetailFutureSeven where CASHFLOWTYPE in ('F08') and ps = 'T01' group by PORTFOLIO_ID) L on l.prod_id = z.prod_id left join /*资产到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) assetexpire from DetailFutureSeven where CASHFLOWTYPE in ('F01','F07','F17','F18') and cash_type = '02' group by PORTFOLIO_ID) E on e.prod_id = z.prod_id left join /*资产中间收息*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) assetpayments from DetailFutureSeven where CASHFLOWTYPE in ('F01','F07','F17','F18') and cash_type = '01' group by PORTFOLIO_ID) F on f.prod_id = z.prod_id left join /*产品到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW)*-1 prodexpire from DetailFutureSeven where CASHFLOWTYPE in ('F16','F24') group by PORTFOLIO_ID) G on g.prod_id = z.prod_id left join /*逆回购首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) nhgsq from DetailFutureSeven where CASHFLOWTYPE in ('F03','F05') AND PS = 'T01' group by PORTFOLIO_ID) H on h.prod_id = z.prod_id left join /*正回购到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) zhgexpire from DetailFutureSeven where CASHFLOWTYPE in ('F02', 'F04') AND PS = 'T02' group by PORTFOLIO_ID) I on i.prod_id = z.prod_id left join /*拆出首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) ccsq from DetailFutureSeven where CASHFLOWTYPE in ('F09') AND PS = 'T01' group by PORTFOLIO_ID) J on j.prod_id = z.prod_id left join /*拆入到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) crexpire from DetailFutureSeven where CASHFLOWTYPE in ('F25') and ps = 'T02' group by PORTFOLIO_ID) K on k.prod_id = z.prod_id ) ) j /*未来7日净现金流*/ on j.prod_id = fp.FINPROD_MARKET_ID left join ( SELECT prod_id, nvl(nhgexpire,0)+nvl(zhgsq,0)+nvl(ccexpire,0)+nvl(crsq,0)+nvl(assetexpire,0)+nvl(assetpayments,0)+nvl(prodexpire,0)+nvl(nhgsq,0)+nvl(zhgexpire,0)+nvl(ccsq,0)+nvl(crexpire,0) amt/*净现金流*/ FROM ( select z.prod_id,A.nhgexpire,B.zhgsq,C.ccexpire,D.crsq,E.assetexpire,F.assetpayments,G.prodexpire, H.nhgsq,I.zhgexpire,J.ccsq,K.crexpire from (select distinct PORTFOLIO_ID prod_id from DetailFutureThirty) z left join /*逆回购到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) nhgexpire from DetailFutureThirty where CASHFLOWTYPE in ('F03','F05') AND PS = 'T02' group by PORTFOLIO_ID) A on a.prod_id = z.prod_id left join /*正回购首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) zhgsq from DetailFutureThirty where CASHFLOWTYPE in ('F02', 'F04') AND PS = 'T01' group by PORTFOLIO_ID) B on b.prod_id = z.prod_id left join /*拆出到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) ccexpire from DetailFutureThirty where CASHFLOWTYPE in ('F09') and ps = 'T02' group by PORTFOLIO_ID) C on c.prod_id = z.prod_id left join /*拆入首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) crsq from DetailFutureThirty where CASHFLOWTYPE in ('F25') and ps = 'T01' group by PORTFOLIO_ID) D on d.prod_id = z.prod_id /*拆入到期*/ left join (select PORTFOLIO_ID prod_id,sum(CASHFLOW)*-1 crsqs from DetailFutureThirty where CASHFLOWTYPE in ('F08') and ps = 'T01' group by PORTFOLIO_ID) L on l.prod_id = z.prod_id left join /*资产到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) assetexpire from DetailFutureThirty where CASHFLOWTYPE in ('F01','F07','F17','F18') and cash_type = '02' group by PORTFOLIO_ID) E on e.prod_id = z.prod_id left join /*资产中间收息*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) assetpayments from DetailFutureThirty where CASHFLOWTYPE in ('F01','F07','F17','F18') and cash_type = '01' group by PORTFOLIO_ID) F on f.prod_id = z.prod_id left join /*产品到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW)*-1 prodexpire from DetailFutureThirty where CASHFLOWTYPE in ('F16','F24') group by PORTFOLIO_ID) G on g.prod_id = z.prod_id left join /*逆回购首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) nhgsq from DetailFutureThirty where CASHFLOWTYPE in ('F03','F05') AND PS = 'T01' group by PORTFOLIO_ID) H on h.prod_id = z.prod_id left join /*正回购到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) zhgexpire from DetailFutureThirty where CASHFLOWTYPE in ('F02', 'F04') AND PS = 'T02' group by PORTFOLIO_ID) I on i.prod_id = z.prod_id left join /*拆出首期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) ccsq from DetailFutureThirty where CASHFLOWTYPE in ('F09') AND PS = 'T01' group by PORTFOLIO_ID) J on j.prod_id = z.prod_id left join /*拆入到期*/ (select PORTFOLIO_ID prod_id,sum(CASHFLOW) crexpire from DetailFutureThirty where CASHFLOWTYPE in ('F25') and ps = 'T02' group by PORTFOLIO_ID) K on k.prod_id = z.prod_id ) ) k /*未来1个月净现金流*/ on k.prod_id = fp.FINPROD_MARKET_ID where 1=1 AND fp.FINPROD_TYPE2 = 'F16'
and fpadd.PROD_MANAGER in
#{item}
and fp.FINPROD_MARKET_ID in
#{item}

select matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((case when ptype.type_10 = '45' then 0 else 1 end) * matchamt.matchamt) netAsset, sum((case when ptype.type_10 = '45' then 0 else 1 end) * matchamt.matchamt)+ nvl(asset.AMT,0) totalAsset, sum((case when ptype.type_10 = '45' then 0 else 1 end) * matchamt.MATCHQTY) netQtyAsset, sum((case when ptype.type_10 = '45' then 0 else 1 end) * matchamt.MATCHQTY)+ nvl(asset.AMT,0) totalQtyAsset from jl_asset_deal_match_amt matchamt left join fin_product prod on matchamt.PROD_ID = prod.FINPROD_MARKET_ID left join fin_product_add prodadd on prod.finprod_id = prodadd.finprod_id left join fin_product_type ptype on matchamt.asset_code = ptype.finprod_id left join TRD_PRODUCT_DEAL deal on matchamt.TRADE_ID = deal.TRADE_ID left join ( SELECT PROD_ID, SUM(CASE WHEN CUR_ASSET_TYPE IN ('01','03','05','06') THEN NVL(AMT,0) ELSE NVL(0-AMT,0) END) AMT FROM ( SELECT DISTINCT DEALADD.PORTFOLIO_ID PROD_ID, DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, deal.TRADE_AMT AMT, DEAL.SHARE_AMT NUM, DECODE(DEAL.FINPROD_TYPE2,'F02',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F03',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07'), 'F04',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F05',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07')) CUR_ASSET_TYPE, DEAL.SETTLE_DATE DEALDATE FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD on DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL on deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 IN ('F02','F04') AND DEAL.IS_CANCEL ='N' and deal.BUSI_TYPE in( '04','05') and nvL(deal.p_trade_id,'NOREV') = 'NOREV' and DEAL.SETTLE_DATE <= to_date(#{searchDate},'YYYY-MM-DD') ) group by PROD_ID,CUR_ASSET_TYPE ) asset ON matchamt.prod_id = asset.PROD_ID where matchamt.matchtype = '02' AND prod.FINPROD_TYPE2 = 'F16' and matchamt.cdate = to_date(#{searchDate},'YYYY-MM-DD') and (deal.MDATE >= to_date(#{searchDate},'YYYY-MM-DD') OR deal.MDATE IS NULL)
and prodadd.PROD_MANAGER in
#{item}
and matchamt.PROD_ID in
#{item}
group by matchamt.prod_id,prodadd.PROD_MANAGER,asset.AMT

SELECT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, SUM(( CASE WHEN ptype.type_10 = '45' THEN 0 ELSE 1 END) * matchamt.matchamt) netAsset, SUM(( CASE WHEN ptype.type_10 = '45' THEN 0 ELSE 1 END) * matchamt.matchamt )+ NVL(asset.AMT,0)+ NVL(matchs.matchamt,0) totalAsset, SUM(( CASE WHEN ptype.type_10 = '45' THEN 0 ELSE 1 END) * matchamt.MATCHQTY) netQtyAsset, SUM(( CASE WHEN ptype.type_10 = '45' THEN 0 ELSE 1 END) * matchamt.MATCHQTY )+ NVL(asset.AMT,0)+ NVL(matchs.matchamt,0) totalQtyAsset FROM jl_asset_deal_match_amt matchamt LEFT JOIN ( SELECT matchamt.PROD_ID, SUM(NVL(pos.TOTAL_NUM/matchamt.MATCHQTY*POS_AMT,matchamt.MATCHQTY)) matchamt FROM JL_ASSET_DEAL_MATCH_AMT matchamt LEFT JOIN FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID LEFT JOIN CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE LEFT JOIN CHB_ASSET_INFO_SUB SUB ON POS.ASSET_CODE = SUB.ASSET_CODE LEFT JOIN FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID WHERE matchamt.CDATE = to_date(#{searchDate},'YYYY-MM-DD') AND matchamt.MATCHTYPE ='01' AND SUB.ASSET_TYPE2 IN ('1902') AND pos.ASSET_CODE IS NOT NULL group by matchamt.PROD_ID ) matchs ON matchamt.PROD_ID = matchs. PROD_ID LEFT JOIN fin_product prod ON matchamt.PROD_ID = prod.FINPROD_MARKET_ID LEFT JOIN fin_product_add prodadd ON prod.finprod_id = prodadd.finprod_id LEFT JOIN fin_product_type ptype ON matchamt.asset_code = ptype.finprod_id LEFT JOIN TRD_PRODUCT_DEAL deal on matchamt.TRADE_ID = deal.TRADE_ID LEFT JOIN ( SELECT PROD_ID, SUM( CASE WHEN CUR_ASSET_TYPE IN ('01', '03', '05', '06') THEN NVL(AMT,0) ELSE NVL(0-AMT,0) END) AMT FROM ( SELECT DISTINCT DEALADD.PORTFOLIO_ID PROD_ID, DEAL.FINPROD_ID ASSET_CODE, DEAL.CCY CCY, deal.TRADE_AMT AMT, DEAL.SHARE_AMT NUM, DECODE(DEAL.FINPROD_TYPE2,'F02',DECODE(DEAL.PS,'T01','06','T02','08','T22','10' ,'T23','08'), 'F03',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07') , 'F04',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F05', DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07')) CUR_ASSET_TYPE, DEAL.SETTLE_DATE DEALDATE FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 IN ('F02', 'F04') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN( '04', '05') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' AND DEAL.SETTLE_DATE <= to_date(#{searchDate},'YYYY-MM-DD') ) GROUP BY PROD_ID, CUR_ASSET_TYPE ) asset ON matchamt.prod_id = asset.PROD_ID WHERE matchamt.MATCHTYPE ='02' AND prod.FINPROD_TYPE2 = 'F16' AND matchamt.cdate = to_date(#{searchDate},'YYYY-MM-DD') AND (deal.MDATE >= to_date(#{searchDate},'YYYY-MM-DD') OR deal.MDATE IS NULL)
and prodadd.PROD_MANAGER in
#{item}
and matchamt.PROD_ID in
#{item}
group by matchamt.prod_id,prodadd.PROD_MANAGER,asset.AMT,matchs.matchamt

select DISTINCT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((nvl(ptl.AMOUNT,0) + nvl(sec.matchamt,0))) openHighMobilityMol, sum((nvl(bvtd.MARKET_VALUE,nvl(bvtds.MARKET_VALUE,0))-nvl(bvtd1.MARKET_VALUE,nvl(bvtds1.MARKET_VALUE,0)))) openHighMobilityDen, sum((nvl(ptl.AMOUNT,0) + nvl(sec.matchamt,0))/(nvl(bvtd.MARKET_VALUE,nvl(bvtds.MARKET_VALUE,0))-nvl(bvtd1.MARKET_VALUE,nvl(bvtds1.MARKET_VALUE,0)))) openHighMobilityAsset FROM ( select PROD_ID,CDATE,MATCHTYPE from JL_ASSET_DEAL_MATCH_AMT GROUP BY PROD_ID,CDATE,MATCHTYPE ) matchamt left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add prodadd on prd.finprod_id = prodadd.finprod_id left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = prd.finprod_id and bvtd.VAL_DATE = matchamt.CDATE and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = prd.finprod_id and bvtd1.VAL_DATE = matchamt.CDATE and bvtd1.DETAIL_DIST = '06' left join BOK_VAL_TABLE_DATA bvtds on bvtds.BOOKSET_ID = matchamt.prod_id and bvtds.VAL_DATE = matchamt.CDATE and bvtds.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtds1 on bvtds1.BOOKSET_ID = matchamt.prod_id and bvtds1.VAL_DATE = matchamt.CDATE and bvtds1.DETAIL_DIST = '06' LEFT JOIN (select ptl.portfolio_id, ptl.CDATE,sum(ptl.AMOUNT) AMOUNT from PTL_CASH_POSITION ptl group by ptl.portfolio_id,ptl.CDATE) ptl on ptl.PORTFOLIO_ID = matchamt.prod_id and ptl.CDATE = matchamt.CDATE left join ( select matchamt.prod_id, sum(matchamt.matchamt) matchamt from jl_asset_deal_match_amt matchamt left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product_type fintype on asset.finprod_id = fintype.finprod_id where matchamt.cdate = to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and matchamt.matchtype = '02' and fintype.type_10 in ('03', '04', '06') and asset.mdate < to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') + 365 group by matchamt.prod_id ) sec on sec.prod_id = matchamt.prod_id where matchamt.cdate = to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and matchamt.matchtype = '02' and prd.OPERATION_TYPE = '02' AND prd.FINPROD_TYPE2 = 'F16' and nvl(bvtd.MARKET_VALUE,nvl(bvtds.MARKET_VALUE,0))-nvl(bvtd1.MARKET_VALUE,nvl(bvtds1.MARKET_VALUE,0))!=0
and prodadd.PROD_MANAGER in
#{item}
and matchamt.PROD_ID in
#{item}
