select DISTINCT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((nvl(ptl.AMOUNT,0) + nvl(sec.matchamt,0))) openHighMobilityMol, sum((nvl(bvtd.MARKET_VALUE,nvl(bvtds.MARKET_VALUE,0))-nvl(bvtd1.MARKET_VALUE,nvl(bvtds1.MARKET_VALUE,0)))) openHighMobilityDen, sum((nvl(ptl.AMOUNT,0) + nvl(sec.matchamt,0))/(nvl(bvtd.MARKET_VALUE,nvl(bvtds.MARKET_VALUE,0))-nvl(bvtd1.MARKET_VALUE,nvl(bvtds1.MARKET_VALUE,0)))) openHighMobilityAsset FROM ( select PROD_ID,CDATE,MATCHTYPE from JL_ASSET_DEAL_MATCH_AMT GROUP BY PROD_ID,CDATE,MATCHTYPE ) matchamt left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add prodadd on prd.finprod_id = prodadd.finprod_id left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = prd.finprod_id and bvtd.VAL_DATE = matchamt.CDATE and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = prd.finprod_id and bvtd1.VAL_DATE = matchamt.CDATE and bvtd1.DETAIL_DIST = '06' left join BOK_VAL_TABLE_DATA bvtds on bvtds.BOOKSET_ID = matchamt.prod_id and bvtds.VAL_DATE = matchamt.CDATE and bvtds.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtds1 on bvtds1.BOOKSET_ID = matchamt.prod_id and bvtds1.VAL_DATE = matchamt.CDATE and bvtds1.DETAIL_DIST = '06' LEFT JOIN (select ptl.portfolio_id, ptl.CDATE,sum(ptl.AMOUNT) AMOUNT from PTL_CASH_POSITION ptl group by ptl.portfolio_id,ptl.CDATE) ptl on ptl.PORTFOLIO_ID = matchamt.prod_id and ptl.CDATE = matchamt.CDATE left join ( select matchamt.prod_id, sum(matchamt.matchamt) matchamt from ( select matchamt.PROD_ID, matchamt.CDATE, NVL(nvl(tp1.FINPROD_ID,pos.ASSET_CODE),matchamt.ASSET_CODE) ASSET_CODE, NVl(pos.TOTAL_NUM/MATCHAMT.matchamt*POS_AMT,matchamt.MATCHAMT) MATCHAMT from JL_ASSET_DEAL_MATCH_AMT matchamt left join FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID left join CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE left join FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID where matchamt.CDATE = to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and matchamt.MATCHTYPE ='01' ) matchamt left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product_type fintype on asset.finprod_id = fintype.finprod_id where matchamt.cdate = to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and fintype.type_10 in ('03', '04', '06') and asset.mdate < to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') + 365 group by matchamt.prod_id ) sec on sec.prod_id = matchamt.prod_id where matchamt.cdate = to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and matchamt.matchtype = '02' and prd.OPERATION_TYPE = '02' AND prd.FINPROD_TYPE2 = 'F16' and nvl(bvtd.MARKET_VALUE,nvl(bvtds.MARKET_VALUE,0))-nvl(bvtd1.MARKET_VALUE,nvl(bvtds1.MARKET_VALUE,0))!=0
