select isDuration, cdate, prodId, prodManager, productDuration, matchamt, hugeRedRatio, saleMin from( select '02' isDuration, to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') cdate, T3.FINPROD_MARKET_ID prodId, T4.PROD_MANAGER prodManager, (T3.MDATE -to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd'))/365 productDuration, prdposition.TDY_SHARE_AMT matchamt, 0 hugeRedRatio, 0 saleMin from fin_product T3 LEFT JOIN FIN_PRODUCT_ADD T4 ON T3.FINPROD_ID = T4.FINPROD_ID LEFT JOIN ( select a.FINPROD_ID, a.TDY_PRIN_AMT, a.TDY_SHARE_AMT, a.TDY_UNIT_VALUE, a.TDY_UNIT_VALUE_SUM from BOK_POSITION_PRD a, (select max(cdate) cdate,FINPROD_ID from BOK_POSITION_PRD where cdate <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') group by FINPROD_ID ) b where a.cdate = b.cdate and a.FINPROD_ID = b.FINPROD_ID ) prdposition on prdposition.FINPROD_ID = T3.FINPROD_ID WHERE T3.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND T3.MDATE >to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND t3.P_FINPROD_ID is null AND t3.FINPROD_TYPE2 = 'F16' AND T3.OPERATION_TYPE = '01' UNION ALL select '02' isDuration, to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') cdate, T3.FINPROD_MARKET_ID prodId, padd.PROD_MANAGER prodManager, (plan.OPEN_MDATE -to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd'))/365 productDuration, prdposition.TDY_SHARE_AMT matchamt, 0 hugeRedRatio, 0 saleMin from fin_product T3 INNER JOIN FIN_PRODUCT_ADD padd ON T3.FINPROD_ID = padd.FINPROD_ID INNER JOIN ( SELECT CASH_ID,FINPROD_ID, OPEN_MDATE FROM ( SELECT plan.CASH_ID, plan.FINPROD_ID, plan.OPEN_MDATE, row_number() over(partition by plan.FINPROD_ID order by abs(plan.OPEN_MDATE-to_date('2020-12-31','yyyy-mm-dd')) ASC) as rnum FROM FIN_OPEN_PLAN plan) a where rnum=1 ) plan ON plan.FINPROD_ID = T3.FINPROD_ID INNER JOIN FIN_OPEN_RULE rule ON plan.CASH_ID = rule.CASH_ID LEFT JOIN ( select a.FINPROD_ID, a.TDY_PRIN_AMT, a.TDY_SHARE_AMT, a.TDY_UNIT_VALUE, a.TDY_UNIT_VALUE_SUM from BOK_POSITION_PRD a, (select max(cdate) cdate,FINPROD_ID from BOK_POSITION_PRD where cdate <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') group by FINPROD_ID ) b where a.cdate = b.cdate and a.FINPROD_ID = b.FINPROD_ID ) prdposition on prdposition.FINPROD_ID = T3.FINPROD_ID WHERE T3.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND T3.MDATE >to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND t3.P_FINPROD_ID is null AND t3.FINPROD_TYPE2 = 'F16' AND T3.OPERATION_TYPE = '02' AND rule.OPEN_MODE = '01' AND padd.DEAL_MODE != '10' UNION ALL select '02' isDuration, to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') cdate, T3.FINPROD_MARKET_ID prodId, padd.PROD_MANAGER prodManager, SUM(totaldeal.productDuration)/SUM(totaldeal.SHARE_AMT) productDuration, SUM(totaldeal.SHARE_AMT) matchamt, 0 hugeRedRatio, 0 saleMin from fin_product T3 INNER JOIN FIN_PRODUCT_ADD padd ON T3.FINPROD_ID = padd.FINPROD_ID LEFT JOIN ( select deal.FINPROD_ID, (deal.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd'))/365*deal.SHARE_AMT productDuration, deal.SHARE_AMT, fp.P_FINPROD_ID from TRD_PRODUCT_DEAL deal LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = deal.FINPROD_ID where deal.FINPROD_TYPE2 = 'F26' AND deal.IS_CANCEL ='N' AND deal.TRADE_STATUS ='01' and deal.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND deal.MDATE > to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') ) totaldeal ON totaldeal.P_FINPROD_ID = T3.FINPROD_ID WHERE T3.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND T3.MDATE > to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND t3.P_FINPROD_ID is null AND t3.FINPROD_TYPE2 = 'F16' AND T3.OPERATION_TYPE = '02' AND padd.DEAL_MODE = '10' GROUP BY T3.FINPROD_MARKET_ID,padd.PROD_MANAGER UNION ALL select '01' isDuration, to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') cdate, T3.FINPROD_MARKET_ID prodId, padd.PROD_MANAGER prodManager, 0 productDuration, prdposition.TDY_SHARE_AMT matchamt, nvl(psp.HUGE_RED_RATIO,0) hugeRedRatio, nvl(psp.SALE_MIN,0) saleMin from fin_product T3 INNER JOIN FIN_PRODUCT_ADD padd ON T3.FINPROD_ID = padd.FINPROD_ID LEFT JOIN FIN_OPEN_PLAN plan ON plan.FINPROD_ID = T3.FINPROD_ID LEFT JOIN PRD_SALE_PARAM psp ON psp.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( select a.FINPROD_ID, a.TDY_PRIN_AMT, a.TDY_SHARE_AMT, a.TDY_UNIT_VALUE, a.TDY_UNIT_VALUE_SUM from BOK_POSITION_PRD a, (select max(cdate) cdate,FINPROD_ID from BOK_POSITION_PRD where cdate <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') group by FINPROD_ID ) b where a.cdate = b.cdate and a.FINPROD_ID = b.FINPROD_ID ) prdposition on prdposition.FINPROD_ID = T3.FINPROD_ID WHERE T3.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND T3.MDATE >to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND t3.P_FINPROD_ID is null AND t3.FINPROD_TYPE2 = 'F16' AND T3.OPERATION_TYPE = '02' AND plan.CASH_ID IS NULL AND padd.DEAL_MODE != '10') WHERE 1=1
