#{item}
GROUP BY PROD.FINPROD_MARKET_ID,PRODADD.PROD_MANAGER

SELECT DISTINCT matchamt.PROD_ID prodId, PRODADD.PROD_MANAGER prodManager, SUM(NVL(assetDuration,0)*matchamt.MATCHQTY) assetDurationMol, SUM(matchamt.MATCHQTY) assetDurationDen, SUM(NVL(assetDuration,0)*matchamt.MATCHQTY)/SUM(matchamt.MATCHQTY) assetDuration, nvl(asset.ssDuration,0) ssDuration FROM JL_ASSET_DEAL_MATCH_AMT matchamt LEFT JOIN TRD_PRODUCT_DEAL dealori ON matchamt.trade_id = dealori.trade_id left join ( SELECT PROD_ID, SUM(NVL(ssDuration,0)*AMT)/SUM(AMT) ssDuration FROM ( SELECT PROD_ID,ssDuration, SUM( CASE WHEN CUR_ASSET_TYPE IN ('01', '03','05','06') THEN NVL(AMT,0) ELSE NVL(0-AMT,0) END) AMT FROM ( SELECT DISTINCT DEALADD.PORTFOLIO_ID PROD_ID, DEAL.FINPROD_ID ASSET_CODE, deal.TRADE_AMT AMT, (deal.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'))/365 ssDuration , DECODE(DEAL.FINPROD_TYPE2,'F02',DECODE(DEAL.PS,'T01','06','T02','08','T22','10' ,'T23','08'), 'F03',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07') , 'F04',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F05', DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07')) CUR_ASSET_TYPE, DEAL.SETTLE_DATE DEALDATE FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 IN ('F02', 'F04') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN('04', '05') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' AND DEAL.SETTLE_DATE <= to_date(#{searchDate},'YYYY-MM-DD')) GROUP BY PROD_ID, ssDuration, CUR_ASSET_TYPE) GROUP BY PROD_ID )asset ON matchamt.prod_id = asset.PROD_ID LEFT JOIN ( SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(val.SDURATION,ptl.END_DAYS_2*365) assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN( select val.SEC_ID,val.SDURATION from (select val.*, row_number() over(partition by val.SEC_ID order by val.VALUE_DATE desc) as rnum from MST_BOND_VALUATION_INFO val where val.VALUE_DATE <= to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and val.SDURATION <> 0 AND val.SDURATION is not null ) val where rnum = 1) val ON PROD.FINPROD_MARKET_ID = val.SEC_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F01' AND ( ABS(NVL(deal.share_amt,0)) + ABS(NVL(deal.trade_amt,0)) != 0) AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*利率型资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(ptl.END_DAYS_2*365,0) assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN CHB_ASSET_INFO CHBA ON DEAL.FINPROD_ID = CHBA.ASSET_CODE LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND CHBA.ASSET_TYPE2 IN( '0401','0402','0403','0404','0405') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*存款类资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, 1/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN CHB_ASSET_INFO CHBA ON DEAL.FINPROD_ID = CHBA.ASSET_CODE LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 NOT IN ('F07') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN( '03', '01') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*回购交易*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(FTP.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.TRADE_ID = FTP.FINPROD_ID LEFT JOIN CHB_ASSET_INFO CHBA ON DEAL.FINPROD_ID = CHBA.ASSET_CODE LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 NOT IN ('F02', 'F04') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN( '04', '05') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*基金资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, 1/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN FIN_PRODUCT FUNDASSET ON DEAL.FINPROD_ID = FUNDASSET.FINPROD_ID WHERE 1 =1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE IN( '06', '07') AND deal.FINPROD_TYPE2 = 'F06' AND DEAL.PS IN ('T01', 'T02', 'T05', 'T19', 'T11', 'T12') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*计划类资产*/ SELECT DISTINCT PLANASSETDETAIL.FINPROD_ID ASSET_CODE, NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN FIN_PRODUCT PLANASSET ON PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE IN( '07', '09', '06') AND DEAL.FINPROD_TYPE2 = 'F17' AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*股票*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUSTINFO ON PROJECTASSET.ISSUER = CUSTINFO.CUSTOMER_ID LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID WHERE DEAL.FINPROD_TYPE2 = 'F10' AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*项目类资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE = '09' AND DEAL.FINPROD_TYPE2 = 'F18' AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*同款存款*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE IN ('01','03') AND DEAL.FINPROD_TYPE2 = 'F07' AND NVL(deal.p_trade_id,'NOREV') = 'NOREV') asset ON dealori.FINPROD_ID = asset.ASSET_CODE AND asset.assetDuration IS NOT NULL INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_MARKET_ID = matchamt.PROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID left JOIN FIN_PRODUCT sec ON sec.FINPROD_ID = matchamt.ASSET_CODE left join (select t.portfolio_id, t.finprod_id, t.DSC_COST_AMT, t.SHARE_AMT, t.ACT_D_YIELD, t.tdy_float_ingpl from (select ptl.*, row_number() over(partition by ptl.portfolio_id, ptl.finprod_id order by ptl.cdate desc) as rnum from ptl_sec_valution ptl where cdate <= to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and ptl.SHARE_AMT <> 0 AND ptl.SHARE_AMT is not null ) t where rnum = 1) ptl on matchamt.prod_id = ptl.portfolio_id and matchamt.asset_code = ptl.finprod_id WHERE matchamt.MATCHTYPE = '02' AND PROD.FINPROD_TYPE2 = 'F16' AND matchamt.CDATE =to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') AND PROD.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') AND PROD.MDATE > to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') AND ((dealori.FINPROD_TYPE2 not IN ('F03','F05','F09')and sec.finprod_market_id is not null) or(dealori.FINPROD_TYPE2 IN ('F03','F05','F09')and ptl.finprod_id is not null)) AND (( dealori.FINPROD_TYPE2 IN ('F10', 'F06', 'F17', 'F18')) OR ( dealori.FINPROD_TYPE2 NOT IN ('F10', 'F06', 'F17', 'F18') AND dealori.VDATE <= to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') AND dealori.MDATE >to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD')))
AND PRODADD.PROD_MANAGER IN
#{item}
AND matchamt.PROD_ID IN
#{item}
GROUP BY matchamt.PROD_ID,PRODADD.PROD_MANAGER,asset.ssDuration

with AssetDuration as ( SELECT DISTINCT matchamt.PROD_ID prodId, PRODADD.PROD_MANAGER prodManager, SUM(NVL(assetDuration,0)*matchamt.MATCHQTY) assetDurationMol, SUM(matchamt.MATCHQTY) assetDurationDen, SUM(NVL(assetDuration,0)*matchamt.MATCHQTY)/SUM(matchamt.MATCHQTY) assetDuration, nvl(asset.ssDuration,0) ssDuration FROM( SELECT matchamt.PROD_ID, matchamt.CDATE, matchamt.ASSET_CODE ASSET_CODE, matchamt.trade_id, matchamt.MATCHTYPE, NVL(pos.TOTAL_NUM/matchamt.MATCHQTY*POS_NUM,matchamt.MATCHQTY) MATCHQTY FROM JL_ASSET_DEAL_MATCH_AMT matchamt LEFT JOIN FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID LEFT JOIN CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE LEFT JOIN FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID WHERE matchamt.CDATE = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') AND matchamt.MATCHTYPE ='02' AND pos.ASSET_CODE IS NULL ) matchamt LEFT JOIN TRD_PRODUCT_DEAL dealori ON matchamt.trade_id = dealori.trade_id left join ( SELECT PROD_ID, SUM(NVL(ssDuration,0)*AMT)/SUM(AMT) ssDuration FROM ( SELECT PROD_ID,ssDuration, SUM( CASE WHEN CUR_ASSET_TYPE IN ('01', '03','05','06') THEN NVL(AMT,0) ELSE NVL(0-AMT,0) END) AMT FROM ( SELECT DISTINCT DEALADD.PORTFOLIO_ID PROD_ID, DEAL.FINPROD_ID ASSET_CODE, deal.TRADE_AMT AMT, (deal.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'))/365 ssDuration , DECODE(DEAL.FINPROD_TYPE2,'F02',DECODE(DEAL.PS,'T01','06','T02','08','T22','10' ,'T23','08'), 'F03',DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07') , 'F04',DECODE(DEAL.PS,'T01','06','T02','08','T22','10','T23','08'), 'F05', DECODE(DEAL.PS,'T01','05','T02','07','T22','09','T23','07')) CUR_ASSET_TYPE, DEAL.SETTLE_DATE DEALDATE FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 IN ('F02', 'F04') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN('04', '05') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' AND DEAL.SETTLE_DATE <= to_date(#{searchDate},'YYYY-MM-DD')) GROUP BY PROD_ID, ssDuration, CUR_ASSET_TYPE) GROUP BY PROD_ID )asset ON matchamt.prod_id = asset.PROD_ID LEFT JOIN ( SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(val.SDURATION,ptl.END_DAYS_2*365) assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN( select val.SEC_ID,val.SDURATION from (select val.*, row_number() over(partition by val.SEC_ID order by val.VALUE_DATE desc) as rnum from MST_BOND_VALUATION_INFO val where val.VALUE_DATE <= to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD') and val.SDURATION <> 0 AND val.SDURATION is not null ) val where rnum = 1) val ON PROD.FINPROD_MARKET_ID = val.SEC_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F01' AND ( ABS(NVL(deal.share_amt,0)) + ABS(NVL(deal.trade_amt,0)) != 0) AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*利率型资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(ptl.END_DAYS_2*365,0) assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN CHB_ASSET_INFO CHBA ON DEAL.FINPROD_ID = CHBA.ASSET_CODE LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND CHBA.ASSET_TYPE2 IN( '0401','0402','0403','0404','0405') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*存款类资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, 1/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN CHB_ASSET_INFO CHBA ON DEAL.FINPROD_ID = CHBA.ASSET_CODE LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 NOT IN ('F07') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN( '03', '01') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*回购交易*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(FTP.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON DEAL.TRADE_ID = FTP.FINPROD_ID LEFT JOIN CHB_ASSET_INFO CHBA ON DEAL.FINPROD_ID = CHBA.ASSET_CODE LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.FINPROD_TYPE2 NOT IN ('F02', 'F04') AND DEAL.IS_CANCEL ='N' AND deal.BUSI_TYPE IN( '04', '05') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*基金资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, 1/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN FIN_PRODUCT FUNDASSET ON DEAL.FINPROD_ID = FUNDASSET.FINPROD_ID WHERE 1 =1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE IN( '06', '07') AND deal.FINPROD_TYPE2 = 'F06' AND DEAL.PS IN ('T01', 'T02', 'T05', 'T19', 'T11', 'T12') AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*计划类资产*/ SELECT DISTINCT PLANASSETDETAIL.FINPROD_ID ASSET_CODE, NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.PORTFOLIO_ID = DEALADD.PORTFOLIO_ID INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID AND PROD.FINPROD_TYPE !='F17' LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID LEFT JOIN FIN_PRODUCT PLANASSET ON PLANASSETDETAIL.P_FINPROD_ID = PLANASSET.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTALDEAL ON deal.TOTLE_TRADE_ID = TOTALDEAL.TOTLE_TRADE_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE IN( '07', '09', '06') AND DEAL.FINPROD_TYPE2 = 'F17' AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*股票*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, /*行内资产/负债编码*/ NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL REVDL ON deal.TRADE_ID = REVDL.P_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEALADD.TRADE_ID = DEAL.TRADE_ID LEFT JOIN FIN_PRODUCT PROJECTASSET ON DEAL.FINPROD_ID = PROJECTASSET.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUSTINFO ON PROJECTASSET.ISSUER = CUSTINFO.CUSTOMER_ID LEFT JOIN FIN_PRODUCT PLANASSETDETAIL ON deal.FINPROD_ID = PLANASSETDETAIL.FINPROD_ID WHERE DEAL.FINPROD_TYPE2 = 'F10' AND NVL(deal.p_trade_id,'NOREV') = 'NOREV' UNION ALL /*项目类资产*/ SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, NVL(PLANASSETDETAIL.MDATE - to_date(#{searchDate,jdbcType=VARCHAR},'YYYY-MM-DD'),0)/365 assetD